use verus::prelude::*;

verus! {
    // A simple sortedness predicate for sequences of u64.
    spec fn sorted(s: Seq<u64>) -> bool {
        forall |i: int, j: int| 
            0 <= i && i < j && j < s.len() 
            ==> s[i] <= s[j]
    }

    /// Returns true iff there is at least one value
    /// appearing in both `r` and `x`.
    ///
    /// Requires that `x` is sorted in non‐decreasing order.
    fn tangent(r: Vec<u64>, x: Vec<u64>) -> (b: bool)
        requires sorted(x@)
        ensures  b <==> exists |ii: int, jj: int|
                      0 <= ii && ii < r@.len() &&
                      0 <= jj && jj < x@.len() &&
                      r@[ii] == x@[jj]
    {
        let mut i: usize = 0;
        let mut j: usize = 0;
        let mut found: bool = false;

        // We scan r and x in lock‐step.  As soon as we see a match,
        // we set `found = true` and break out.
        while i < r.len() && j < x.len() && !found
            invariant 0 <= i && i <= r.len()
            invariant 0 <= j && j <= x.len()
            invariant
                // found == true  <==>  there is already a match in the
                // prefixes r[0..i] and x[0..j]
                found 
                <==> 
                exists |ii: int, jj: int|
                  0 <= ii && ii < i as int &&
                  0 <= jj && jj < j as int &&
                  r@.index(ii) == x@.index(jj)
            decreases (r.len() - i) + (x.len() - j)
        {
            if r[i] < x[j] {
                i += 1;
            } else if r[i] > x[j] {
                j += 1;
            } else {
                // r[i] == x[j], we found a common element
                found = true;
            }
        }

        found
    }
}